-- ═══════════════════════════════════════════════════════════════════════════
-- IRAC kazuslar — IQTISODIY + KONSTITUTSIYAVIY yo'nalishlar (to'liq qamrov)
-- 20260902 migration 5 ta yo'nalishni qamrab olgan; ushbu qo'shimcha
-- iqtisodiy va konstitutsiyaviy yo'nalishlarni ham to'ldiradi (har biri ≥10).
--
-- Idempotent: kategoriyalarda kazus allaqachon mavjud bo'lsa, qayta kiritilmaydi.
-- ═══════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.irac_cases
    WHERE category IN ('iqtisodiy', 'konstitutsiyaviy')
  ) THEN
  END IF;
END $$;
